        return []

    rows = len(grid)
    cols = len(grid[0])

    # Find vertical separator (all 6s in a column)
    sep_col = -1
    for c in range(cols):
        if all(grid[r][c] == 6 for r in range(rows)):
            sep_col = c
            break

    # Find horizontal separator (full row of identical same values)
    sep_row = -1
    if sep_col == -1:
        for r in range(rows):
            if all(grid[r][c] == grid[r][0] for c in range(cols)):
                sep_row = r
                break

    if sep_col != -1:
        # Vertical separator: keep columns 0 to sep_col-1
        result = [[2 if grid[r][c] != 0 else 0 for c in range(sep_col)] for r in range(rows)]
    elif sep_row != -1:
        # Horizontal separator: keep rows 0 to sep_row-1
        result = [[2 if grid[r][c] != 0 else 0 for c in range(cols)] for r in range(sep_row)]
    else:
        # No separator: keep entire grid, convert non-zero to 2
        result = [[2 if grid[r][c] != 0 else 0 for c in range(cols)] for r in range(rows)]

    return result
